<script setup lang="ts">
import { computed,reactive,ref,watch } from 'vue';
import { Download,PackageCheck,FolderOpen,Cloud,Check,FileArchive,ChevronDown,Upload,HardDrive,Server,CloudUpload,ArrowRight,CircleCheck } from '@lucide/vue';
import { desk,safely,request,operation,apiPath,downloadDeployment,openDeploymentFolder,binary,loadProject,notify,openBrowse,openView,assertProject } from './store';
import { bytes,when,newestReleases,type Data } from './model';
import { viewSections,sectionLabel } from './presentation';
import Segmented from './Segmented.vue';
import PlayerProgramUpdates from './PlayerProgramUpdates.vue';
import { emptyHosting,hostingRequest,type HostingMethod } from './hosting-history';
import { useHostingHistory } from './hosting-history-state';
import { savedHostingPresentation } from './player-update-presentation';
const releases=computed(()=>newestReleases(desk.project?.releases));
const release=ref(''),platform=ref('windows-x64'),packageInput=ref<HTMLInputElement|null>(null),packageFile=ref<File|null>(null),plan=ref<Data|null>(null),agent=ref('0.1.2'),dropping=ref(false);
const program=reactive({sourceDirectory:'',version:'',launchPath:'DreamingFishUpdater.exe'});
const destination=ref(''),instance=ref('');const method=ref<HostingMethod>('export');
const hosting=reactive(emptyHosting()),remember=ref(false);
const savedHosting=computed(()=>desk.project?.savedHosting),savedStatus=computed(()=>savedHostingPresentation(savedHosting.value));
const hostingScope=computed(()=>desk.project?.id===desk.projectId?JSON.stringify([desk.state.settingsFile||'',desk.state.dataDirectory||'',desk.projectId,desk.project.createdAt||'']):'');
const hostingHistory=reactive(useHostingHistory(hostingScope,hosting,method));
const result=ref<Data|null>(null);
const programs=ref<Data[]>([]),currentProgram=ref('');
const platforms=[{id:'windows-x64',label:'Windows x64'},{id:'linux-x64',label:'Linux x64'}];
const methods=[{id:'export',title:'仅导出',detail:'生成静态目录，自行放到任意 HTTP 服务器。',icon:HardDrive},{id:'webdav',title:'WebDAV',detail:'导出后用 WebDAV 或 HTTP PUT 上传。',icon:Server},{id:'s3',title:'对象存储',detail:'导出后上传到兼容 S3 的存储桶。',icon:CloudUpload}];
const steps=computed(()=>[{title:'填写玩家更新地址',detail:desk.project?.publicBaseUrl||'玩家电脑上的更新器从这个地址获取更新。',done:Boolean(desk.project?.publicBaseUrl),action:desk.project?.publicBaseUrl?'修改':'去填写',go:()=>openView('settings','project')},{title:'发布整合包',detail:releases.value.length?`当前 ${releases.value[0].displayVersion}`:'确认文件和维护设置已经发布。',done:releases.value.length>0,action:'查看改动',go:()=>openView('changes','changes')},{title:'发布玩家端程序',detail:currentProgram.value?`当前 ${currentProgram.value}`:'选择用于这个项目的更新器版本。',done:Boolean(currentProgram.value),action:'管理程序',go:()=>openView('delivery','programs')},{title:'制作部署包',detail:'下载 ZIP，接入启动器并完成一次启动测试。',done:false,action:'',go:null}]);
let platformRequest=0;
watch(()=>[desk.project,platform.value],()=>{const generation=++platformRequest;programs.value=[];currentProgram.value='';safely(async()=>{const details=await request(apiPath(`?platform=${encodeURIComponent(platform.value)}`));if(generation===platformRequest){programs.value=[...(details.playerPrograms||[])].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));currentProgram.value=details.currentProgramVersion||'';}});},{immediate:true});
// Automatic uploads finish in the background; show their latest result when the owner opens this page.
watch(()=>desk.section==='hosting'&&desk.projectId,open=>{if(open&&desk.project?.savedHosting)safely(loadProject);});
watch(()=>desk.browseValues['deployment-output'],value=>{if(value)destination.value=value;});
watch(()=>desk.browseValues['hosting-output'],value=>{if(value){hosting.outputDirectory=value;hostingHistory.touch();}});
watch(()=>desk.projectId,()=>{release.value='';plan.value=null;packageFile.value=null;result.value=null;remember.value=false;});
function choosePackage(file:File|null){packageFile.value=file;plan.value=null;}
async function checkPackage(){if(!packageFile.value)return;await operation(async()=>{plan.value=await binary(apiPath(`/program-package?fileName=${encodeURIComponent(packageFile.value!.name)}`),packageFile.value!);},'正在上传并识别玩家端…');}
async function publishPackage(){await operation(async()=>{await request(apiPath('/program-package'),'POST',{id:plan.value?.id,minimumBootstrapVersion:agent.value});plan.value=null;packageFile.value=null;await loadProject();notify('玩家端程序已发布');},'正在发布玩家端…');}
async function publishDirectory(){await operation(async()=>{await request(apiPath('/programs'),'POST',{...program,platform:platform.value,minimumBootstrapVersion:agent.value});await loadProject();notify('玩家端程序已发布');});}
async function writeDeployment(){await operation(async()=>{result.value=await request(apiPath('/deployment'),'POST',{platform:platform.value,releaseId:release.value||releases.value[0]?.releaseId,outputDirectory:destination.value});notify('部署包已生成');},'正在写入部署包…');}
async function prepareInstance(){await operation(async()=>{result.value=await request(apiPath('/instance'),'POST',{platform:platform.value,releaseId:release.value||releases.value[0]?.releaseId,instanceDirectory:instance.value});notify('玩家实例已准备');},'正在准备实例…');}
async function distribute(){if(desk.busy||hostingHistory.busy||hostingHistory.loading)return;const owner=desk.projectId,scope=hostingScope.value,visit=hostingHistory.visit(),values={...hosting},keep=remember.value&&method.value!=='export',payload={...hostingRequest(method.value,values),...(keep?{remember:true}:{})},path=apiPath(method.value==='export'?'/distribution-export':method.value==='webdav'?'/distribution-webdav':'/distribution-s3');await hostingHistory.remember();assertProject(owner);if(scope!==hostingScope.value||visit!==hostingHistory.visit())throw new Error('管理项目已切换，请重新确认本次上传');await operation(async()=>{result.value=await request(path,'POST',payload);if(scope!==hostingScope.value||visit!==hostingHistory.visit())return;for(const field of ['password','secretAccessKey','sessionToken'] as const)if(hosting[field]===values[field])hosting[field]='';if(keep){remember.value=false;await loadProject();}notify(keep?'已上传并保存设置，之后发布时会自动上传':'静态分发内容已处理完成');},'正在准备分发…');}
async function uploadSaved(){await operation(async()=>{result.value=await request(apiPath('/distribution-saved'),'POST',{});await loadProject();notify('已用保存的设置导出并上传');},'正在导出并上传…');}
async function setHostingAuto(enabled:boolean){await operation(async()=>{await request(apiPath('/hosting-saved'),'POST',{action:'auto',enabled});await loadProject();notify(enabled?'已开启发布后自动上传':'已关闭自动上传，发布后请点击“立即上传”');});}
async function forgetHosting(){if(!confirm('删除保存的上传设置和密钥吗？\n之后发布不会再自动上传，再次上传时需要重新填写密钥。'))return;await operation(async()=>{await request(apiPath('/hosting-saved'),'POST',{action:'forget'});await loadProject();notify('已删除保存的密钥');});}
</script>
<template>
 <div class="view delivery-view"><section class="stage">
  <header class="stage-toolbar"><Segmented class="section-tabs" :items="viewSections.delivery" :model-value="desk.section" label="发放" @update:model-value="safely(()=>openView('delivery',$event))"/><strong class="section-title">{{sectionLabel('delivery',desk.section)}}</strong><span class="toolbar-spacer"/>
   <template v-if="desk.section==='programs'"><span class="current-tag">当前 {{currentProgram||'未发布'}}</span><div class="select-capsule"><select v-model="platform" aria-label="程序平台"><option v-for="p in platforms" :key="p.id" :value="p.id">{{p.label}}</option></select><ChevronDown :size="13"/></div></template>
   <span v-else-if="desk.section==='hosting'" class="toolbar-note">让 HTTP、WebDAV 或对象存储提供玩家下载</span></header>

  <div v-if="desk.section==='deployment'" class="list-scroll"><div class="page-column">
   <section class="hero-card"><span class="hero-art"><FileArchive :size="40"/></span><div><span class="overline">首次发放</span><h2>把整合包交给玩家</h2><p>选择已经发布的版本，生成包含更新器与启动说明的部署包。</p><small>{{desk.project?.displayName}} · {{desk.project?.publicBaseUrl||'玩家更新地址未填写'}}</small></div></section>
   <p v-if="desk.project?.packRoot" class="field-help">已启用整合包外层目录：发布后，已有玩家在下次启动时自动开始更新外层文件，不需要重新分发。新生成的部署包也包含这项设置。</p>
   <ol class="step-cards"><li v-for="(step,i) in steps" :key="i" :class="{done:step.done}"><span class="step-mark"><Check v-if="step.done" :size="14"/><template v-else>{{i+1}}</template></span><div><strong>{{step.title}}</strong><p>{{step.detail}}</p><button v-if="step.go" class="text-action" @click="safely(step.go)">{{step.action}}<ArrowRight :size="13"/></button></div></li></ol>
   <section class="form-card"><div class="form-grid"><label>整合包版本<div class="select-capsule wide"><select v-model="release"><option value="">最新发布 {{releases[0]?.displayVersion||''}}</option><option v-for="r in releases" :key="r.releaseId" :value="r.releaseId">{{r.displayVersion}} · #{{r.sequence}}</option></select><ChevronDown :size="13"/></div></label><div class="field"><span class="field-label">玩家平台</span><Segmented v-model="platform" :items="platforms" label="玩家平台"/></div></div>
    <div class="form-actions"><button class="accent large" :disabled="desk.busy||!releases.length||!currentProgram||!desk.project?.publicBaseUrl" @click="safely(()=>downloadDeployment(release||releases[0]?.releaseId,platform,currentProgram))"><Download :size="17"/>生成并下载部署 ZIP</button><span v-if="!desk.project?.publicBaseUrl" class="field-help">先在设置里填写玩家更新地址。</span><span v-else-if="!currentProgram" class="field-help">先发布这个平台的玩家端程序。</span><span v-else class="field-help">生成后，按包内说明接入玩家的 PCL、HMCL 或其他启动器。</span></div></section>
   <div v-if="desk.deploymentDownload?.projectId===desk.projectId" class="notice-card" :class="{success:desk.deploymentDownload.state==='saved'}" role="status" aria-live="polite"><CircleCheck v-if="desk.deploymentDownload.state==='saved'" :size="20"/><Download v-else :size="20"/><div><strong>{{desk.deploymentDownload.state==='saved'?'部署包已保存':desk.deploymentDownload.state==='canceled'?'已取消保存部署包':'已交给浏览器下载'}}</strong><p class="download-destination">{{desk.deploymentDownload.destination||'没有开始生成或下载部署包。'}}</p><small v-if="desk.deploymentDownload.state==='saved'">{{bytes(desk.deploymentDownload.size)}} · 按包内说明接入玩家的启动器。</small><small v-else-if="desk.deploymentDownload.state==='browser'">请在浏览器下载列表查看进度、保存位置或拦截提示。</small></div><button v-if="desk.deploymentDownload.receiptId" @click="safely(openDeploymentFolder)"><FolderOpen :size="16"/>打开所在文件夹</button></div>
   <details class="disclosure-card"><summary>写入管理端目录 / 准备现有实例</summary><label>部署包输出目录<div class="field-with-button"><input v-model="destination" placeholder="管理端所在电脑或服务器的目录"><button type="button" aria-label="浏览目录" @click="openBrowse('directory','deployment-output',destination)"><FolderOpen :size="16"/></button></div></label><button :disabled="!destination||desk.busy" @click="safely(writeDeployment)">写入部署包</button><label class="spaced">现有实例目录<input v-model="instance" placeholder="包含 mods、config 的玩家实例目录"></label><button :disabled="!instance||desk.busy" @click="safely(prepareInstance)">准备此实例</button></details>
   <p v-if="result" class="notice-card success"><CircleCheck :size="17"/>{{result.outputDirectory||result.instanceDirectory||'处理完成'}}</p>
  </div></div>

  <div v-else-if="desk.section==='programs'" class="list-scroll"><div class="page-column">
   <PlayerProgramUpdates v-if="desk.project?.playerUpdatePolicy" :platform="platform" :programs="programs"/>
   <p v-else class="field-help">一键发布官方新版、自动发布与暂停需要管理服务 0.3.2 或更新版本。当前仍可手动上传程序。</p>
   <details class="disclosure-card" :open="!desk.project?.playerUpdatePolicy||undefined"><summary>手动上传玩家端发行 ZIP</summary><p class="field-help">通常用上方的“发布给玩家”即可。国内服务器从 GitHub 下载很慢时，可以在自己电脑上下载官方发行 ZIP 后在这里上传；自己构建或从其他渠道拿到发行包时也在这里上传。检查通过后点击“批准并发布”。</p>
   <div class="drop-card" :class="{dropping}" @dragover.prevent="dropping=true" @dragleave="dropping=false" @drop.prevent="dropping=false;choosePackage($event.dataTransfer?.files[0]||null)"><span class="hero-art small"><FileArchive :size="28"/></span><strong>{{packageFile?.name||'选择或拖入玩家端发行 ZIP'}}</strong><p>{{packageFile?bytes(packageFile.size):'保留原发行包结构，系统会识别平台和版本。'}}</p><div class="drop-actions"><button @click="packageInput?.click()"><Upload :size="15"/>选择 ZIP</button><button class="accent" :disabled="!packageFile||desk.busy" @click="safely(checkPackage)">检查发行包</button></div><input ref="packageInput" type="file" accept=".zip" hidden @change="choosePackage(($event.target as HTMLInputElement).files?.[0]||null)"></div>
   <div v-if="plan" class="notice-card" :class="plan.publishable?'success':'warning'"><PackageCheck :size="20"/><div><strong>已识别 {{plan.version}} · {{plan.platform}}</strong><p>{{plan.problem||plan.launcher||plan.sourceRelative||''}}</p></div><button class="accent" :disabled="desk.busy||!plan.publishable" @click="safely(publishPackage)">批准并发布</button></div></details>
   <section class="list-card"><header><strong>管理端已有的程序版本</strong><span>{{platforms.find(p=>p.id===platform)?.label}} · {{programs.length}} 个</span></header><div v-for="(p,i) in programs" :key="p.manifestSha256" class="list-card-row"><span class="release-dot" :class="{latest:p.version===currentProgram}"/><strong>{{p.version}}</strong><span class="subtle">{{p.platform}}</span><span class="subtle">{{when(p.createdAt)}}</span><span v-if="p.version===currentProgram" class="current-tag">当前</span></div><p v-if="!programs.length" class="card-note">还没有这个平台的玩家端程序。</p></section>
   <details class="disclosure-card"><summary>从已有程序目录发布</summary><div class="form-grid"><label>程序目录<input v-model="program.sourceDirectory"></label><label>程序版本<input v-model="program.version"></label><label>启动文件<input v-model="program.launchPath"></label><label>最低 Agent 版本<input v-model="agent"></label></div><button :disabled="!program.sourceDirectory||desk.busy" @click="safely(publishDirectory)">发布目录中的程序</button></details>
  </div></div>

  <div v-else class="list-scroll"><div class="page-column">
   <section v-if="savedHosting" class="form-card saved-hosting" aria-label="已保存的上传设置">
    <header class="saved-hosting-header"><span class="choice-icon"><CloudUpload :size="20"/></span><div><strong>已保存上传设置</strong><small>{{savedHosting.provider==='s3'?'对象存储 · ':savedHosting.provider==='webdav'?'WebDAV · ':''}}{{savedHosting.destination}}</small></div><button v-if="!savedHosting.problem" class="accent" :disabled="desk.busy" @click="safely(uploadSaved)"><Cloud :size="16"/>立即上传</button></header>
    <p v-if="!savedHosting.problem" class="saved-hosting-meta">静态目录 {{savedHosting.outputDirectory}}<template v-if="savedHosting.accessKeyId"> · Access Key ID {{savedHosting.accessKeyId}}</template><template v-else-if="savedHosting.username"> · 用户名 {{savedHosting.username}}</template><template v-if="savedHosting.savedAt"> · 保存于 {{when(savedHosting.savedAt)}}</template></p>
    <label v-if="!savedHosting.problem" class="check toggle-line player-auto-publish"><span>发布后自动上传<small>管理服务运行时，发布整合包、发布或暂停玩家端程序、修改玩家端首页后，约半分钟内自动导出并上传；内容没有变化时不上传。</small></span><input type="checkbox" class="switch" :checked="Boolean(savedHosting.autoUpload)" :disabled="desk.busy" @change="safely(()=>setHostingAuto(($event.target as HTMLInputElement).checked))"></label>
    <p v-if="savedStatus.title" class="player-auto-status" :class="savedStatus.tone" role="status"><strong>{{savedStatus.title}}</strong><span v-if="savedStatus.detail">{{savedStatus.detail}}</span><small v-if="savedHosting.autoStatus?.uploadedAt">上次上传 {{when(savedHosting.autoStatus.uploadedAt)}}</small></p>
    <div class="form-actions"><button type="button" :disabled="desk.busy" @click="safely(forgetHosting)">删除保存的密钥</button><span class="field-help">密钥保存在管理服务所在电脑的管理数据目录，和项目签名私钥放在一起，网页上不会再显示。</span></div>
   </section>
   <p v-if="savedHosting" class="hosting-change-note">要换存储桶、地址或密钥，在下方重新填写，勾选“保存密钥”后上传即可替换。</p>
   <div class="choice-cards" role="radiogroup" aria-label="托管方式"><button v-for="item in methods" :key="item.id" role="radio" :aria-checked="method===item.id" :class="{active:method===item.id}" @click="method=item.id as HostingMethod;hostingHistory.touch()"><span class="choice-icon"><component :is="item.icon" :size="20"/></span><strong>{{item.title}}</strong><small>{{item.detail}}</small><span class="option-radio"/></button></div>
   <form class="form-card" @input="hostingHistory.touch" @change="hostingHistory.touch" @submit.prevent="safely(distribute)">
    <section class="hosting-history" aria-label="外部托管填写历史"><div class="hosting-history-tools"><label>填写历史<div class="select-capsule wide"><select v-model="hostingHistory.selected" :disabled="hostingHistory.loading||hostingHistory.busy||!hostingHistory.entries.length" @change="hostingHistory.restoreSelected"><option value="">{{hostingHistory.loading?'正在读取…':hostingHistory.entries.length?'选择一条填写历史':'暂无填写历史'}}</option><option v-for="entry in hostingHistory.entries" :key="entry.id" :value="entry.id">{{hostingHistory.label(entry)}} · {{when(new Date(entry.savedAt).toISOString())}}</option></select><ChevronDown :size="13"/></div></label><button type="button" :disabled="!hostingHistory.selected||hostingHistory.loading||hostingHistory.busy" @click="hostingHistory.restoreSelected">回填</button><button type="button" :disabled="!hostingHistory.ready||hostingHistory.busy||desk.busy" @click="async()=>{if(await hostingHistory.remember())notify('填写历史已保存在本机')}">保存本次填写</button><button type="button" :disabled="!hostingHistory.selected||hostingHistory.loading||hostingHistory.busy" @click="hostingHistory.forget">删除这条历史</button></div><p class="field-help">按管理连接和项目保存在本机，最近 10 条；打开时恢复最近一次填写。上传前自动记住，也可手动保存。</p><p class="field-help">记住 Access Key ID；密码、Secret Access Key、临时会话令牌及地址中的账号密码、查询参数不保存，回填后需重新输入。</p><p v-if="hostingHistory.error" class="history-error" role="status">{{hostingHistory.error}}</p></section>
    <label>静态目录<div class="field-with-button"><input v-model="hosting.outputDirectory" placeholder="管理端生成静态文件的目录" aria-describedby="hosting-directory-help" required><button type="button" class="labelled" aria-label="选择静态分发目录" @click="openBrowse('directory','hosting-output',hosting.outputDirectory)"><FolderOpen :size="16"/>选择目录</button></div><small id="hosting-directory-help">在管理端所在电脑或服务器上选择目录，用于保存导出的分发文件。</small></label>
    <template v-if="method==='webdav'"><label>WebDAV / HTTP PUT 地址<input v-model="hosting.baseUrl" type="url" required></label><div class="form-grid"><label>用户名<input v-model="hosting.username" autocomplete="off"></label><label>密码<input v-model="hosting.password" type="password" autocomplete="off"></label></div></template>
    <template v-if="method==='s3'"><label>S3 Endpoint<input v-model="hosting.endpoint" type="url" required></label><div class="form-grid"><label>Region<input v-model="hosting.region" required></label><label>Bucket<input v-model="hosting.bucket" required></label><label>目录前缀<input v-model="hosting.prefix"></label><label>寻址方式<div class="select-capsule wide"><select v-model="hosting.addressingStyle" aria-describedby="s3-addressing-help"><option value="PATH">Path</option><option value="VIRTUAL_HOST">Virtual hosted</option></select><ChevronDown :size="13"/></div><small id="s3-addressing-help">阿里云 OSS 请选择 Virtual hosted。</small></label><label>Access Key ID<input v-model="hosting.accessKeyId" autocomplete="off" required></label><label>Secret Access Key<input v-model="hosting.secretAccessKey" type="password" autocomplete="off" required></label></div><details class="disclosure-inline"><summary>临时会话令牌</summary><input v-model="hosting.sessionToken" type="password" autocomplete="off" aria-label="临时会话令牌"></details></template>
    <template v-if="method!=='export'"><label class="check hosting-remember"><input v-model="remember" type="checkbox">保存密钥，之后发布时自动上传</label><p v-if="remember" class="field-help hosting-remember-help">上传成功后才保存。密钥保存在管理服务所在电脑的管理数据目录，和项目签名私钥同等保护，也会包含在加密备份里。建议使用只授权这个存储桶的子账号密钥；临时会话令牌会过期，不能保存。</p></template>
    <div class="form-actions"><button class="accent large" :disabled="desk.busy||hostingHistory.loading||hostingHistory.busy"><Cloud :size="16"/>{{method==='export'?'导出静态内容':'导出并上传'}}</button><span class="field-help">{{method!=='export'&&remember?'网页上不会再显示保存的密钥。':'密码、Secret Access Key 和临时令牌仅用于本次上传。'}}</span></div></form>
   <div v-if="result" class="notice-card success"><CircleCheck :size="20"/><div><strong>处理完成</strong><p>{{result.outputDirectory||result.destination}}</p><small>{{result.objectCount||result.fileCount||result.completedFileCount||''}} 项 · {{bytes(result.totalObjectBytes||result.totalBytes||0)}}</small></div></div>
  </div></div>
 </section></div>
</template>
